/** A policy's color axis, shared by the `pill` and `progress` modifiers — `off`/unmatched is neutral
 *  (`brand`), `warn` is `warning`, and `block` is `danger`. */
function policyColor(policy: DriftSeverity): "danger" | "warning" | "brand" {
  if (policy === "block") return "danger";
  if (policy === "warn") return "warning";
  return "brand";
}

replacements.oldString:
/** A policy's `pill` color modifier — `off`/unmatched gets no modifier (neutral). */
function policyPillClass(policy: DriftSeverity): string {
  if (policy === "block") return "instui-pill -color-danger";
  if (policy === "warn") return "instui-pill -color-warning";
  return "instui-pill";
}

